questionvariables.text:
scenario : rand(4);              /* 0 linear, 1 quadratic, 2 cubic, 3 exponential */
ta : if scenario=0 then "linear" elseif scenario=1 then "quadratic" elseif scenario=2 then "cubic" else "exponential";
opts : [["linear", scenario=0, "Linear"],["quadratic", scenario=1, "Quadratic"],["cubic", scenario=2, "Cubic"],["exponential", scenario=3, "Exponential"]];
